<?php
declare(strict_types=1);
const AI_TECHNOLOGY_PROMPT_VERSION='assembly-grades-20261025.1-luna';
const AI_TECHNOLOGY_TYPES=['sew','special','overlock','iron','hand','qc','pack'];
function aiKeys(array $data,array $allowed,array $required=[]):void{if(array_diff(array_keys($data),$allowed)||array_diff($required,array_keys($data)))fail('AI вернул неверные поля. Повторите текущую часть.',502);}
function aiString(mixed $v,int $limit,bool $required=false):string{if(!is_string($v)||!preg_match('//u',$v)||preg_match('/[\x00-\x08\x0B\x0C\x0E-\x1F]/',$v))fail('Некорректный текст AI',502);$v=trim($v);if(preg_match_all('/./us',$v)>$limit||($required&&$v===''))fail('Некорректная длина текста AI',502);return $v;}
function aiInteger(mixed $v,int $min,int $max,bool $nullable=false):?int{if($nullable&&$v===null)return null;if(!is_int($v)||$v<$min||$v>$max)fail('Некорректное число AI',502);return $v;}
function aiNoIdentifiers(string $text,int $status=422):void{
 if(preg_match('~(*UCP)(?:https?://|www\.|[\w.+-]+@[\w.-]+\.[a-z]{2,}|\bsk-[\w-]+|\+?\d[\d ()-]{8,}\d|\b(?:ФИО|ИНН|СНИЛС|паспорт|телефон|email|e-mail|заказчик|клиент|сотрудник)\b)~iu',$text)||preg_match('/\b[А-ЯЁ][а-яё]+\s+[А-ЯЁ][а-яё]+\s+[А-ЯЁ][а-яё]+\b/u',$text))fail('Оставьте только техническое описание изделия, без имён, контактов и данных предприятия.',$status);
}
function aiTechnicalInput(array $input):array{$p=textField($input,'product',180,true);$d=textField($input,'description',6000);aiNoIdentifiers($p.' '.$d);return ['product'=>$p,'description'=>$d,'cutting_in_route'=>false,'production_context'=>'Промышленный пошив; полные комплекты деталей поступают из самостоятельного подразделения подготовки; его работы не входят в сборку'];}
function aiTechnicalPrivacy(array $technical,array $company,array $order):void{$text=$technical['product'].' '.$technical['description'];foreach([$company['name'],$order['customer']??'',user()['name'],...array_column($company['passport']['people']??[],'name')] as $name){$name=trim((string)$name);if(strlen($name)>=5&&preg_match('~'.preg_quote($name,'~').'~iu',$text))fail('Уберите имена и названия предприятия или заказчика из описания.');}}
function aiJsonReply(string $reply):array{$reply=trim($reply);if(preg_match('/^```(?:json)?\s*([\s\S]*?)\s*```$/i',$reply,$m))$reply=$m[1];try{$o=json_decode($reply,true,128,JSON_THROW_ON_ERROR);}catch(JsonException){fail('AI вернул незавершённую часть. Уже готовые узлы сохранены; повторите эту часть.',502);}if(!is_array($o)||array_is_list($o))fail('AI вернул неверный JSON',502);return $o;}
function aiTexts(mixed $v):array{if(!is_array($v)||!array_is_list($v))fail('Некорректные уточнения AI',502);return array_map(function($x){$s=aiString($x,600,true);aiNoIdentifiers($s,502);return $s;},$v);}
function aiOutlinePage(string $reply):array{
 $o=aiJsonReply($reply);aiKeys($o,['groups','has_more','continuation','assumptions','questions'],['groups','has_more','continuation','assumptions','questions']);if(!is_array($o['groups'])||!array_is_list($o['groups'])||!count($o['groups'])||!is_bool($o['has_more']))fail('AI не сформировал узлы',502);$groups=[];
 foreach($o['groups'] as $g){if(!is_array($g))fail('Неверный узел AI',502);aiKeys($g,['name','description','after'],['name','description','after']);$name=aiString($g['name'],180,true);$description=aiString($g['description'],1200);aiNoIdentifiers($name.' '.$description,502);if(!is_array($g['after'])||!array_is_list($g['after']))fail('Неверные связи узлов AI',502);$after=[];foreach($g['after'] as $n)$after[]=aiInteger($n,1,PHP_INT_MAX);$groups[]=['name'=>$name,'description'=>$description,'after'=>$after];}
 return ['groups'=>$groups,'has_more'=>$o['has_more'],'continuation'=>aiString($o['continuation'],1600),'assumptions'=>aiTexts($o['assumptions']),'questions'=>aiTexts($o['questions'])];
}
function aiOperationsPage(string $reply):array{
 $o=aiJsonReply($reply);aiKeys($o,['operations','has_more','continuation','questions'],['operations','has_more','continuation','questions']);if(!is_array($o['operations'])||!array_is_list($o['operations'])||!count($o['operations'])||!is_bool($o['has_more']))fail('AI не вернул операции узла',502);$ops=[];
 foreach($o['operations'] as $op){if(!is_array($op))fail('Неверная операция AI',502);$fields=['name','type','estimated_seconds','setup_minutes','equipment','grade','notes','catalog_variant'];aiKeys($op,[...$fields,'specialization'],$fields);$name=aiString($op['name'],300,true);$type=aiString($op['type'],20,true);if(!in_array($type,AI_TECHNOLOGY_TYPES,true))fail('Неизвестный вид работы AI',502);$equipment=aiString($op['equipment'],300);$notes=aiString($op['notes'],1200);aiNoIdentifiers($name.' '.$equipment.' '.$notes,502);$machine=productionItem(['type'=>$type,'name'=>$name,'equipment'=>$equipment,'specialization'=>$op['specialization']??null]);if($machine['type']==='special'&&!isset(SPECIAL_MACHINE_NAMES[$machine['specialization']]))fail('Неизвестная специализация спецмашины AI',502);$ops[]=['name'=>$name,'type'=>$machine['type'],'specialization'=>$machine['specialization']??null,'seconds'=>null,'estimated_seconds'=>aiInteger($op['estimated_seconds'],1,86400,true),'setup_minutes'=>aiInteger($op['setup_minutes'],0,1440),'equipment'=>$equipment,'grade'=>aiInteger($op['grade'],1,99,true),'notes'=>$notes,'catalog_variant'=>aiString($op['catalog_variant'],60),'source'=>'Предложение AI; применимость и время проверяет технолог','batch'=>20,'norm_reviewed'=>false,'grade_reviewed'=>false];}
 return ['operations'=>$ops,'has_more'=>$o['has_more'],'continuation'=>aiString($o['continuation'],1600),'questions'=>aiTexts($o['questions'])];
}
